/**
 * Test that the MODCA parser recognises carriage control (0x5A) as the Structured Field
 * delimeter
 *
 * @throws Exception *
 */
@Test
public void testReadNextStructuredField1() throws Exception {
    // carriage control (0x5A) delimits structured fields,
    // and control is handed to readStructuredField(DataInputStream)
    byte[][] goodInputStream = new byte[][] { new byte[] { CARRIAGE_CONTROL_CHAR } };
    for (byte[] b : goodInputStream) {
        try {
            new MODCAParser(new ByteArrayInputStream(b)).readNextStructuredField();
            fail("BAD SF should throw EOF: " + byteArrayToString(b));
        } catch (EOFException eof) {
            //passed
        }
    }
    // EOFException thrown when reading the input stream are caught and
    // a null value is returned
    byte[][] badInputStream = new byte[][] { new byte[] {}, new byte[] { CARRIAGE_RETURN }, new byte[] { LINE_FEED } };
    for (byte[] b : badInputStream) {
        UnparsedStructuredField usf = new MODCAParser(new ByteArrayInputStream(b)).readNextStructuredField();
        assertNull(usf);
    }
}

/**
 * Test that the MODCA parser correctly constructs an UnparsedStructuredField
 * from a well formed structured field
 *
 * @throws Exception *
 */
@Test
public void testReadNextStructuredField2() throws Exception {
    // no extension data
    //SFTypeID
    testSF(//SFTypeID
    (byte) 0xd3, //SFTypeID
    (byte) 0xa8, //SFTypeID
    (byte) 0x89, //flags excluding the bits for
    (byte) 0, //extension present, segmented data and padding present
    false, false, new byte[] { 0, 0 }, new byte[] { 1 }, null);
    // with extension data
    //SFTypeID
    testSF(//SFTypeID
    (byte) 0xd3, //SFTypeID
    (byte) 0xa8, //SFTypeID
    (byte) 0x89, //flags excluding the bits for
    (byte) 0, //extension present, segmented data and padding present
    false, false, new byte[] { 0, 0 }, new byte[] { 1 }, new byte[] { 10 });
    // with ignored reserved bits
    //SFTypeID
    testSF(//SFTypeID
    (byte) 0xd3, //SFTypeID
    (byte) 0xa8, //SFTypeID
    (byte) 0x89, //flags excluding the bits for
    (byte) 0, //extension present, segmented data and padding present
    false, false, new byte[] { 1, 2 }, new byte[] { 1 }, null);
    // with padding present and segmented data
    //SFTypeID
    testSF(//SFTypeID
    (byte) 0xd3, //SFTypeID
    (byte) 0xa8, //SFTypeID
    (byte) 0x89, //flags excluding the bits for
    (byte) (1 << 3), //extension present, segmented data and padding present
    true, true, new byte[] { 0, 0 }, new byte[] { 1 }, null);
    // with flags non zero
    //SFTypeID
    testSF(//SFTypeID
    (byte) 0xd3, //SFTypeID
    (byte) 0xa8, //SFTypeID
    (byte) 0x89, //flags excluding the bits for
    (byte) (1 << 3), //extension present, segmented data and padding present
    false, false, new byte[] { 0, 0 }, new byte[] { 1 }, null);
}

