 */
@Test
public void testRemoveElementPenalty1() throws Exception {
    LinkedList lst = new LinkedList();
    lst.add(new KnuthBox(4000, null, false));
    lst.add(new KnuthPenalty(0, 0, false, null, false));
    lst.add(new KnuthBox(4000, null, false));
